import { describe, expect, it } from 'vitest';
import { Chess } from 'chess.js';
import positions from './trainerPositions.json';
import themes from './trainerThemes.json';

// The endgame library is generated by scripts/endgames; these guard against a bad build reaching players.
describe('endgame library', () => {
    const themeIds = new Set(themes.map(t => t.id));

    it('has 42 themes, each with an explanation and a sensible rating', () => {
        expect(themes).toHaveLength(42);
        expect(themeIds.size).toBe(42);
        for (const t of themes) {
            expect(t.explanation.length).toBeGreaterThan(80);
            expect(t.rating).toBeGreaterThanOrEqual(400);
            expect(t.rating).toBeLessThanOrEqual(2800);
        }
    });

    it('has legal, unique positions, each in a known theme', () => {
        const ids = new Set<string>();
        for (const p of positions as { id: string; theme: string; fen: string; target: string; rating: number }[]) {
            expect(themeIds.has(p.theme)).toBe(true);
            expect(['win', 'draw']).toContain(p.target);
            expect(() => new Chess(p.fen)).not.toThrow();
            expect(new Chess(p.fen).isGameOver()).toBe(false);
            expect(ids.has(p.id)).toBe(false);
            ids.add(p.id);
        }
    });
});
